---@class RankRewardService
local RankRewardService = Class("RankRewardService")

function RankRewardService.new(facade)
    local obj = RankRewardService.New()
    obj.facade = facade
    obj.CoClick = nil
    return obj
end

function RankRewardService:UpdateInfo()
    SetButtonAction(self.facade.BtnList, Bind(self, self.OnClick))
end

function RankRewardService:OnClick()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
    self.CoClick = cs_coroutine.start(function()
        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIWorldBossRankRewardDialog
        },{})
    end)
end

function RankRewardService:Dispose()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
end

return RankRewardService